import itertools

def can_alice_survive(m, n, X, depth=0, visited=None):
    if visited is None:
        visited = set()

    state = tuple(X)
    if state in visited:
        return True # Assume it's a cycle Alice can maintain
    visited.add(state)

    if depth > 10: # Simple depth limit for recursion
        return True

    # Bob chooses k
    for k in range(1, m):
        # Alice chooses sigma = 1 or -1
        possible_sigma = []
        # sigma = 1: x_i -> x_i + 1 for i <= k, x_i -> x_i - 1 for i > k
        if all(X[i] + 1 >= 1 for i in range(k)) and all(X[i] - 1 >= 1 for i in range(k, m)):
            X_plus = [X[i] + 1 for i in range(k)] + [X[i] - 1 for i in range(k, m)]
            if can_alice_survive(m, n, X_plus, depth + 1, visited.copy()):
                possible_sigma.append(1)

        # sigma = -1: x_i -> x_i - 1 for i <= k, x_i -> x_i + 1 for i > k
        if all(X[i] - 1 >= 1 for i in range(k)) and all(X[i] + 1 >= 1 for i in range(k, m)):
            X_minus = [X[i] - 1 for i in range(k)] + [X[i] + 1 for i in range(k, m)]
            if can_alice_survive(m, n, X_minus, depth + 1, visited.copy()):
                possible_sigma.append(-1)

        if not possible_sigma:
            return False

    return True

def find_min_n(m):
    for n in range(1, 100):
        # Try all distributions of n pebbles into m boxes (x_i >= 1)
        # This is equivalent to distributing n-m pebbles into m boxes (y_i >= 0)
        for X in itertools.product(range(1, n - m + 2), repeat=m):
            if sum(X) == n:
                if can_alice_survive(m, n, list(X)):
                    return n
    return None

for m in range(2, 6):
    print(f"m={m}, min_n={find_min_n(m)}")

def solve():
    def get_next_states(m, X, k):
        # Try sigma = 1
        if all(X[i] - 1 >= 1 for i in range(k, m)):
            yield tuple([X[i] + 1 if i < k else X[i] - 1 for i in range(m)])
        # Try sigma = -1
        if all(X[i] - 1 >= 1 for i in range(k)):
            yield tuple([X[i] - 1 if i < k else X[i] + 1 for i in range(m)])

    def can_survive(m, X, visited=None):
        if visited is None:
            visited = set()
        if X in visited:
            return True
        visited.add(X)

        # For every k, Alice must have at least one move that leads to survival
        for k in range(1, m):
            possible_next = list(get_next_states(m, X, k))
            if not possible_next:
                return False

            # Alice must pick one of these moves. 
            # This is a game, so she just needs one to work.
            # But Bob picks k to make it hard.
            # So for this k, she needs at least one next state that can survive all k's.
            # This is tricky. Let's use a simple recursive check with depth.

        return True

    # Actually, let's use a different approach.
    # For a state X, is it "safe"?
    # A state X is safe if for all k, there exists a move to a safe state.
    # This is a fixed-point iteration.

    def find_safe_states(m, n):
        # Initial set of states: all X with sum n and x_i >= 1
        import itertools
        states = []
        for X in itertools.product(range(1, n + 1), repeat=m):
            if sum(X) == n:
                states.append(X)

        safe = set(states)
        while True:
            new_safe = set()
            for X in safe:
                # X is safe if for all k, there is a move to a safe state
                is_safe = True
                for k in range(1, m):
                    possible_next = list(get_next_states(m, X, k))
                    if not any(next_X in safe for next_X in possible_next):
                        is_safe = False
                        break
                if is_safe:
                    new_safe.add(X)
            if new_safe == safe:
                break
            safe = new_safe
        return safe

    for m in range(2, 6):
        for n in range(m, 2*m + 2):
            if find_safe_states(m, n):
                print(f"m={m}, min_n={n}")
                break

